
const categories=[['Todos','◈'],['Rações pet','🐕'],['Produção animal','🐄'],['Grãos e sementes','🌽'],['Fertilizantes','🌱'],['Solo e jardinagem','🪴'],['Sanidade animal','💊'],['Controle de pragas','🐜'],['Ferramentas','🛠️'],['Acessórios','🐾'],['Gestão e atendimento','📦'],['Piscinas e tratamento de água','🏊'],['Aves ornamentais e silvestres','🐦'],['Aquarismo avançado','🐠'],['Higiene e limpeza','🧼'],['Irrigação e hidráulica','💧'],['Apicultura e criação','🐝']];
