function makeLineGuide(r){
 const t=r.name.toLocaleLowerCase('pt-BR');
 const bird=/calopsit|papaga|trinca|canári|canario|aves|farinhada/.test(t);
 const fish=/discus|carnívoros de superfície|tropical|bottom fish|goldfish|basic/.test(t)&&/Poytara|Alcon Peixes/.test(r.brand);
 const cat=/gatos|babycat|indoor|fit 32|sterilised/.test(t);
 const puppy=/filhot|puppy|babycat/.test(t);
 const senior=/7\+|senior|idos/.test(t);
 const neutered=/castrad|sterili/.test(t);
 const wet=/sachê|sache/.test(t);
 const small=/mini|pequenas/.test(t);
 let audience=bird?'Aves da espécie indicada no nome':fish?'Peixes ornamentais conforme espécie indicada':cat?'Gatos':'Cães';
 if(puppy)audience+=' em crescimento';else if(senior)audience+=' idosos';else audience+=' na fase indicada na embalagem';
 if(neutered)audience+='; perfil para castrados';
 if(small)audience+='; porte pequeno';
 const base=bird?'Produto alimentar destinado à espécie de ave indicada; a função na dieta depende de ser alimento completo, mistura ou complemento.':fish?'Alimento para peixes ornamentais; tamanho do grânulo, flutuabilidade e hábito alimentar precisam corresponder à espécie.':wet?'Alimento úmido: maior teor de água que rações secas; verifique se o rótulo diz completo ou complementar.':'Alimento comercial para a espécie e fase de vida indicadas; uma fórmula completa é planejada para fornecer nutrientes essenciais.';
 const usage=bird?'Confirme a espécie e se é alimento completo ou complementar. Introduza mudanças gradualmente, mantenha água limpa e observe o consumo.':fish?'Ofereça apenas a quantidade recomendada no rótulo e que os peixes consumam sem sobras excessivas; monitore a água.':wet?'Verifique a tabela da embalagem, ajuste quando combinado com ração seca e refrigere sobras conforme o rótulo.':'Confira espécie, idade, porte, peso, condição corporal e a tabela da embalagem. Faça a transição de dieta gradualmente e mantenha água fresca.';
 const fun=bird?'A composição e o processamento influenciam a distribuição dos nutrientes; aves podem selecionar sementes de misturas.':fish?'O alimento fornece nutrientes na água; sobras aumentam a carga orgânica e podem prejudicar a qualidade da água.':cat?'A dieta para felinos deve atender exigências próprias da espécie, incluindo nutrientes essenciais como taurina.':'A dieta fornece energia, aminoácidos, ácidos graxos, vitaminas e minerais; valores exatos variam entre receitas.';
 return {publico:audience,desc:`${r.name}: referência de linha comercial de ${r.brand}. ${base}`,func:fun,uso:usage,curiosidade:brandInsights[r.brand]||'Produtos da mesma marca podem apresentar composições distintas.',cuidados:'Guia educativo por linha, NÃO ficha de composição verificada. Confirme rótulo físico, espécie, lote, validade, níveis de garantia e tabela alimentar. Casos clínicos exigem veterinário.',detailLevel:'Guia individual de linha • dados comerciais a conferir'};
}
