let selected='Todos',active=null,tab=0,onlyFav=false;let favorites=JSON.parse(localStorage.getItem('petlele_favs')||'[]');const $=id=>document.getElementById(id);function renderBrandTiles(){const el=$('brandTiles');if(!el)return;const b=[...new Set(brandedFeed.map(x=>x.brand))];el.replaceChildren();b.forEach(n=>{const btn=document.createElement('button');btn.type='button';btn.textContent=n+' · '+brandedFeed.filter(x=>x.brand===n).length;btn.onclick=()=>selectBrand(n);el.appendChild(btn)})}function selectBrand(n){selected='Todos';onlyFav=false;$('q').value='';init();$('brand').value=n;filter();$('grid').scrollIntoView({behavior:'smooth',block:'start'})}function init(){brandOptions();renderBrandTiles(); $('total').textContent=rows.length;$('nav').innerHTML=categories.map(([n,i])=>`<button class="nav ${n===selected?'active':''}" onclick="setCat('${n}')">${i} &nbsp;${n}</button>`).join('');$('chips').innerHTML=categories.map(([n])=>`<button class="chip ${n===selected?'on':''}" onclick="setCat('${n}')">${n}</button>`).join('');filter()}function setCat(n){pageLimit=24;selected=n;onlyFav=false;$('side').classList.remove('open');init()}let pageLimit=24;
function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function filter(){let q=normalized($('q').value);let list=rows.filter(x=>(selected==='Todos'||x.cat===selected)&&(!$('brand')?.value||x.brand===$('brand').value)&&(!onlyFav||favorites.includes(x.name))&&normalized([x.name,x.desc,x.cat,x.func,x.brand].join(' ')).includes(q));$('count').textContent=list.length+' resultados';$('grid').innerHTML=list.length?list.slice(0,pageLimit).map(x=>`<button class="card" onclick="openProduct(${rows.indexOf(x)})"><div class="icon">${escapeHTML(x.icon)}</div><div class="cat">${escapeHTML(x.cat)}</div><div class="brandtag">${escapeHTML(x.brand||'Multimarcas')}</div>${x.detailLevel?'<div class="brandtag" style="color:#ffda52">★ Ficha detalhada</div>':''}<h3>${escapeHTML(x.name)}<span class="arrow">↗</span></h3><p>${escapeHTML(x.desc)}</p></button>`).join(''):'<div class="empty">Nenhum resultado. Tente outro termo ou categoria.</div>';let more=$('catalogMore');if(more){more.replaceChildren();if(list.length>pageLimit){let b=document.createElement('button');b.textContent=`Ver mais produtos (${list.length-pageLimit} restantes)`;b.onclick=()=>{pageLimit+=24;filter()};more.appendChild(b)}}}
function openProduct(i){active=rows[i];tab=0;$('modal').classList.add('show');document.body.style.overflow='hidden';$('mcat').textContent=active.cat;$('mtitle').textContent=active.icon+' '+active.name;$('msummary').textContent=(active.publico?'Indicado: '+active.publico+' • ':'')+active.desc+' • Categoria comercial: '+(active.brand||'Multimarcas')+(active.marcasReferencia?' • Marcas para pesquisar (não vinculadas automaticamente ao item): '+active.marcasReferencia:'');renderTab();renderFav();$('warn').textContent='⚠️ Atenção: '+active.cuidados;$('sources').innerHTML='<div style="padding:14px;background:#242014;border:1px solid #756021;border-radius:12px"><b>🦴 Tudo aqui dentro da PETLELE</b><br>Esta ficha, seus cuidados, curiosidades e o assistente estão integrados ao próprio site. Para dosagens de produtos comerciais, leia também a embalagem física antes de orientar o cliente.</div>';$('question').textContent='Qual é a conduta mais segura ao orientar o uso deste produto?';$('answers').innerHTML=['Seguir rótulo/bula e verificar a necessidade de orientação técnica','Usar a mesma quantidade para todos os casos','Misturar com outros produtos sem conferir compatibilidade'].map((a,i)=>`<button onclick="answer(${i})">${a}</button>`).join('');$('quizresult').textContent=''}function renderTab(){let ts=['O que é','Como funciona','Como usar','Curiosidades','Cuidados'];$('tabs').innerHTML=ts.map((t,i)=>`<button class="${tab===i?'selected':''}" onclick="tab=${i};renderTab()">${t}</button>`).join('');$('content').textContent=[active.desc,active.func,active.uso,active.curiosidade,active.cuidados][tab]}function answer(i){$('quizresult').textContent=i===0?'✓ Correto! Segurança e indicação adequada vêm primeiro.':'✕ Não é seguro. Sempre confira a indicação e as instruções oficiais.'}function closeModal(){$('modal').classList.remove('show');document.body.style.overflow=''}function toggleFav(){favorites=favorites.includes(active.name)?favorites.filter(n=>n!==active.name):[...favorites,active.name];localStorage.setItem('petlele_favs',JSON.stringify(favorites));renderFav()}function renderFav(){$('fav').textContent=favorites.includes(active.name)?'★ Salvo nos favoritos':'☆ Salvar favorito'}function randomProduct(){openProduct(Math.floor(Math.random()*rows.length))}function showFavorites(){selected='Todos';onlyFav=true;$('q').value='';init();window.scrollTo({top:430,behavior:'smooth'})}function openGuide(){let i=rows.findIndex(x=>x.name==='Atendimento consultivo');openProduct(i)}
function calcKg(){const a=Number($('pprice').value),b=Number($('pweight').value);$('kgout').textContent=a>=0&&b>0&&$('pprice').value!==''?'R$ '+(a/b).toFixed(2).replace('.',',')+' por kg':'Informe preço e peso válidos.'}
function calcNpk(){const m=Number($('npkmass').value),match=$('npkform').value.trim().match(/^(\d{1,2})\s*[-/]\s*(\d{1,2})\s*[-/]\s*(\d{1,2})$/);if(!(m>0)||!match){$('npkout').textContent='Informe massa positiva e fórmula no formato 04-14-08.';return}const a=match.slice(1).map(Number);$('npkout').textContent=`N: ${(m*a[0]/100).toFixed(2)} kg • P₂O₅: ${(m*a[1]/100).toFixed(2)} kg • K₂O: ${(m*a[2]/100).toFixed(2)} kg`}
function exportFavs(){const blob=new Blob([JSON.stringify(rows.filter(x=>favorites.includes(x.name)),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='petlele-favoritos.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

$('q').addEventListener('input',()=>{pageLimit=24;onlyFav=false;filter()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});init();

function normalized(s){return String(s||'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function quickAsk(q){$('chatq').value=q;askPet(new Event('submit'))}
function askPet(e){e.preventDefault();const q=$('chatq').value.trim();if(!q)return;const log=$('chatlog');const addBubble=(msg,cls)=>{const d=document.createElement('div');d.className='bubble '+cls;d.textContent=msg;log.appendChild(d);log.scrollTop=log.scrollHeight};addBubble(q,'human');$('chatq').value='';const nq=normalized(q);const stop=new Set(['como','funciona','funcionar','usar','uso','sobre','produto','para','qual','quais','oque','que','uma','com','posso','devo','onde','serve','serve','me','fale','explique','cuidados','curiosidades','marca','marcas','dosagem','dose','quanto','colocar','piscina','agua','raçao','racao']);const words=nq.replace(/[^a-z0-9 -]/g,' ').split(/\s+/).filter(w=>w.length>2&&!stop.has(w));const scored=rows.map(r=>{const n=normalized(r.name),b=normalized(r.brand),hay=normalized([r.desc,r.func,r.cat].join(' '));let score=0;if(nq.includes(n)&&n.length>4)score+=25;for(const w of words){if(n.includes(w))score+=5;else if(b.includes(w))score+=2;else if(hay.includes(w))score+=1}return {r,score}}).sort((a,b)=>b.score-a.score);const best=scored[0];if(!best||best.score<3){addBubble('Não encontrei um produto com segurança nessa pergunta. Tente escrever o nome exato do item (ex.: cloro granulado, barrilha leve, ração para cães adultos). Para produto de marca, confira a embalagem e o fabricante.','bot');return}const r=best.r;let answer='📌 '+r.name+'\n';if(/curios|sabia/.test(nq))answer+='💡 '+r.curiosidade;else if(/cuidado|risco|mistur|perig|segur/.test(nq))answer+='⚠️ '+r.cuidados;else if(/como usar|aplic|dose|dosag|quant|coloc|prepar/.test(nq))answer+='📋 '+r.uso+'\n\n⚠️ Para quantidade exata, consulte o rótulo do produto específico.';else if(/funcion|serve|efeito|acao/.test(nq))answer+='⚙️ '+r.func;else answer+='📖 '+r.desc+'\n\n⚙️ '+r.func+'\n\n📋 '+r.uso;answer+='\n\nFonte: ficha educativa local PETLELE (não é consulta em tempo real).';addBubble(answer,'bot')}

function getStock(){try{return JSON.parse(localStorage.getItem('petlele_stock')||'[]')}catch{return []}}
function saveStock(){const n=$('stockName').value.trim(),t=$('stockNote').value.trim();if(!n)return;const a=getStock();a.unshift({n,t});localStorage.setItem('petlele_stock',JSON.stringify(a.slice(0,300)));$('stockName').value='';$('stockNote').value='';renderStock()}
function renderStock(){const box=$('stockList');if(!box)return;box.replaceChildren();const a=getStock();if(!a.length){box.textContent='Nenhuma anotação ainda.';return}a.slice(0,25).forEach((r,i)=>{const d=document.createElement('div');d.style.cssText='background:#252114;padding:10px;border-radius:9px';const b=document.createElement('b');b.textContent=r.n;d.appendChild(b);const p=document.createElement('div');p.textContent=r.t;d.appendChild(p);const bt=document.createElement('button');bt.textContent='Remover';bt.style.cssText='margin-top:6px;padding:5px 8px';bt.onclick=()=>{a.splice(i,1);localStorage.setItem('petlele_stock',JSON.stringify(a));renderStock()};d.appendChild(bt);box.appendChild(d)})}
function exportStock(){const blob=new Blob([JSON.stringify(getStock(),null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='petlele-meu-balcao.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
renderStock();

// Extensões locais: comparação, calculadoras, histórico e trilha de estudo.
const normPet=t=>String(t||'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
function findPet(t){const n=normPet(t);return rows.find(x=>normPet(x.name)===n)||rows.find(x=>normPet(x.name).includes(n)&&n.length>3)}
function comparePet(){const a=findPet($('compareA').value),b=findPet($('compareB').value),el=$('compareResult');if(!a||!b){el.textContent='Não encontrei um dos itens no catálogo. Selecione nomes sugeridos.';return}el.textContent=`${a.name}  ×  ${b.name}\n\nCATEGORIA\n${a.cat}  ×  ${b.cat}\n\nFINALIDADE A\n${a.desc}\n\nFINALIDADE B\n${b.desc}\n\nCOMO FUNCIONA A\n${a.func}\n\nCOMO FUNCIONA B\n${b.func}\n\nCUIDADOS A\n${a.cuidados}\n\nCUIDADOS B\n${b.cuidados}\n\nComparação educativa; confirme o rótulo de cada marca.`}
function calcUnit(){const v=Number($('priceValue').value),q=Number($('priceAmount').value);$('unitResult').textContent=Number.isFinite(v)&&Number.isFinite(q)&&v>=0&&q>0?`R$ ${(v/q).toFixed(2).replace('.',',')} por ${$('priceUnit').value}.`:'Informe preço válido e quantidade maior que zero.'}
function calcPool(){const a=['poolL','poolW','poolD'].map(x=>Number($(x).value));$('poolResult').textContent=a.every(x=>Number.isFinite(x)&&x>0)?`Volume estimado: ${(a[0]*a[1]*a[2]*1000).toLocaleString('pt-BR',{maximumFractionDigits:0})} litros. Não use este número isoladamente para dosar produtos: consulte análises da água e rótulos.`:'Preencha as três dimensões com números maiores que zero.'}
function getRecent(){try{return JSON.parse(localStorage.getItem('petlele_recent')||'[]')}catch{return []}}
function recordRecent(n){let a=getRecent().filter(x=>x!==n);a.unshift(n);localStorage.setItem('petlele_recent',JSON.stringify(a.slice(0,12)));renderRecent()}
function renderRecent(){const el=$('recentProducts');if(!el)return;el.replaceChildren();const a=getRecent();if(!a.length){el.textContent='Nenhuma consulta recente.';return}a.forEach(n=>{const b=document.createElement('button');b.textContent='↗ '+n;b.style.cssText='display:block;margin:5px 0;background:#302812;color:#ffe182;border:1px solid #61501b;border-radius:8px;padding:7px';b.onclick=()=>{const i=rows.findIndex(x=>x.name===n);if(i>=0)openProduct(i)};el.appendChild(b)})}
function clearRecent(){localStorage.removeItem('petlele_recent');renderRecent()}
const lessons=[
['Rações para cães e gatos','Aprenda a distinguir alimento completo, complementar e coadjuvante; fase de vida, espécie, porte, calorias e leitura dos níveis de garantia. Dietas terapêuticas exigem acompanhamento veterinário.','O que verificar antes de indicar uma ração?','Espécie, idade, condição corporal, indicação do fabricante e necessidades do animal.'],
['Rações para aves e animais de produção','Diferencie ração inicial, crescimento, postura e manutenção. Necessidades variam por espécie e fase; mudanças bruscas de dieta e formulações improvisadas podem prejudicar os animais.','Ração de postura serve para pintinhos?','Não. Cada fase exige formulação apropriada.'],
['Grãos, sementes e farelos','Milho é principalmente energético; farelo de soja é fonte proteica; sementes variam em gordura e fibra. Misturas isoladas podem ser nutricionalmente incompletas.','Alpiste sozinho é dieta completa para toda ave?','Não. A dieta depende da espécie e pode requerer alimento formulado.'],
['Fertilizantes NPK','NPK expressa nitrogênio (N), fósforo como P₂O₅ e potássio como K₂O. A fórmula não determina sozinha a indicação: análise de solo e cultura são essenciais.','O que significa 10-10-10?','Teores nominais de 10% N, 10% P₂O₅ e 10% K₂O.'],
['Ureia, calcário e solo','Ureia agrícola fornece nitrogênio; calcário corrige acidez; gesso agrícola não substitui calagem. Ureia pecuária tem uso técnico restrito e risco de intoxicação.','Calcário e gesso fazem a mesma coisa?','Não. Têm funções diferentes na química do solo.'],
['Defensivos e controle de pragas','Inseticidas, fungicidas e herbicidas têm alvos distintos. Registro, cultura, alvo, receituário quando aplicável, EPIs e bula são indispensáveis.','É seguro recomendar pela cor da embalagem?','Não. Verifique ingrediente ativo, registro e indicação.'],
['Medicamentos veterinários','Confira espécie, peso, idade, princípio ativo, apresentação, contraindicações e necessidade de receita. Nunca adapte doses entre espécies.','Um antipulgas de cão serve em gato?','Não necessariamente; alguns são tóxicos para gatos.'],
['Suplementos e sal mineral','Suplementos não substituem dieta equilibrada. Sais minerais e proteinados são formulados para grupos específicos; o consumo deve seguir orientação técnica.','Mais suplemento é sempre melhor?','Não. Excesso pode causar danos.'],
['Jardinagem e substratos','Terra vegetal, fibra de coco, perlita, vermiculita e húmus têm propriedades diferentes de drenagem, aeração e retenção de água.','Fibra de coco é fertilizante completo?','Não. É sobretudo componente de substrato.'],
['Ferramentas e equipamentos','Aprenda a selecionar ferramenta por tarefa, material, capacidade, manutenção e proteção. Pulverizadores exigem limpeza e compatibilidade conforme fabricante.','O que conferir num pulverizador?','Capacidade, bicos, vedação, aplicação prevista e manual.'],
['Pássaros, peixes e pequenos animais','Alimentos e acessórios variam por espécie. Avalie habitat, dieta, qualidade da água, temperatura e bem-estar antes de orientar compras.','Ração de peixe serve para qualquer espécie?','Não. Há necessidades e hábitos alimentares distintos.'],
['Estoque e armazenamento','Use FEFO (primeiro que vence, primeiro que sai), evite calor, umidade, pragas e embalagens danificadas; segregue químicos incompatíveis e alimentos.','Qual lote deve sair primeiro?','O que vence primeiro, respeitando integridade e condições de armazenagem.'],
['Atendimento profissional','Pergunte para qual animal, planta ou piscina, qual problema, idade/volume/medidas e produto atual. Não diagnostique sem habilitação; registre dúvidas.','Quando não souber uma resposta?','Explique a limitação, confira a embalagem e encaminhe ao profissional apropriado.'],
['Piscinas e tratamento de água','Estude pH, alcalinidade, desinfecção, filtração e medição. Produtos incompatíveis podem liberar gases perigosos; nunca misture cloro com ácidos.','Posso misturar cloro e redutor de pH?','Não. Nunca misture produtos químicos entre si.'],
['Comparações e cálculos avançados','Compare preço por kg ou litro, interprete porcentagens de nutrientes, calcule volume geométrico e confira densidade/unidade antes de orientar.','Uma fórmula NPK maior é sempre melhor?','Não. Depende da necessidade e da recomendação técnica.']
];
function completedLessons(){try{return JSON.parse(localStorage.getItem('petlele_lessons')||'[]')}catch{return []}}
function renderAcademy(){const root=$('academyModules');root.replaceChildren();lessons.forEach(([title,body,q,answer],i)=>{const d=document.createElement('details');d.className='course-row';const sum=document.createElement('summary');sum.textContent=`${completedLessons().includes(i)?'✅':'📖'} Módulo ${i+1} — ${title}`;d.appendChild(sum);const p=document.createElement('p');p.textContent=body;d.appendChild(p);const qel=document.createElement('p');qel.innerHTML='<strong>🧠 Questão de revisão:</strong>';qel.appendChild(document.createTextNode(' '+q));d.appendChild(qel);const rev=document.createElement('button');rev.textContent='Ver resposta';const ans=document.createElement('p');ans.hidden=true;ans.textContent=answer;rev.onclick=()=>{ans.hidden=!ans.hidden};d.append(rev,ans);const done=document.createElement('button');done.textContent='Marcar como estudado';done.onclick=()=>{const a=completedLessons();if(!a.includes(i))a.push(i);localStorage.setItem('petlele_lessons',JSON.stringify(a));renderAcademy()};d.appendChild(done);root.appendChild(d)});$('academyProgress').textContent=`Progresso: ${completedLessons().length} de ${lessons.length} módulos estudados.`}
